select.where:
and duty.del_flag = 0
and user.nick_name like concat('%',#{doctorId},'%')

and DATE(duty.duty_date) = DATE(#{dutyDate})
and duty.duty_period = #{dutyPeriod}
and h.id = #{hospitalId}
and dept.dept_id = #{deptId}
and duty.appointments_num = #{appointmentsNum}
and duty.appointments_num_made = #{appointmentsNumMade}

mapper.update:
update duty_info
doctor_id = #{doctorId}, duty_date = #{dutyDate}, duty_period = #{dutyPeriod}, appointments_num = #{appointmentsNum}, appointments_num_made = #{appointmentsNumMade}, registration_fee = #{registrationFee}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where schedule_id = #{scheduleId}
